## 五、withRetry：指数退避重试机制

```typescript
// packages/llms/src/index.ts（概念性实现）
async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number,
  onRetry: (attempt: number, error: InvokeError) => void
): Promise<T> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      if (attempt > 0) await sleep(100)  // 重试前等待
      return await fn()
    } catch (error) {
      // 立即终止：用户取消
      if (error.name === 'AbortError') throw error

      // 立即终止：不可重试错误
      if (error instanceof InvokeError && !error.retryable) throw error

      // 已达重试上限
      if (attempt === maxRetries) throw error

      // 通知 UI 显示重试状态
      onRetry(attempt + 1, error)
      await sleep(100)  // 错误后额外等待
    }
  }
}
```

**重试次数配置**：
```typescript
const agent = new PageAgent({
  maxRetries: 3,  // 初始调用 + 最多 3 次重试 = 最多 4 次总调用
})
```

