## 八、Custom Tools：扩展工具系统

### 8.1 添加自定义工具

```typescript
import { tool } from 'page-agent'
import { z } from 'zod'

const agent = new PageAgent({
  model: 'qwen3.5-plus',
  customTools: {
    // 添加新工具：截图保存
    screenshot: tool({
      description: '截取当前页面截图并上传到服务器',
      inputSchema: z.object({
        filename: z.string().describe('截图文件名'),
      }),
      async execute({ filename }) {
        const canvas = document.createElement('canvas')
        // ... 截图逻辑
        await uploadToServer(canvas.toDataURL(), filename)
        return { success: true, url: `https://cdn.example.com/${filename}` }
      }
    }),
  }
})
```

### 8.2 覆盖内置工具

```typescript
// 覆盖 ask_user，改用自定义对话框而非默认 Panel
customTools: {
  ask_user: tool({
    description: '向用户提问并等待回答',
    inputSchema: z.object({ question: z.string() }),
    async execute({ question }) {
      return new Promise((resolve) => {
        MyCustomDialog.show(question, (answer) => {
          resolve({ answer })
        })
      })
    }
  })
}
```

### 8.3 删除工具

```typescript
// 禁止 agent 执行任意 JS（安全敏感场景）
customTools: {
  execute_javascript: null,
  navigate: null,  // 禁止页面跳转
}
```

### 8.4 Page Filters（Beta）：URL 感知工具激活

```typescript
customTools: {
  approve_order: tool({
    description: '审批当前订单',
    inputSchema: z.object({ orderId: z.string() }),
    pageFilter: {
      include: ['https://erp.company.com/orders/*'],
      exclude: ['*/archive/*'],
    },
    async execute({ orderId }) {
      // 只在订单页面可用
    }
  })
}
```

